 230:                     Err(_) => return Ok(None),
 231:                     Ok(f) => f,
 232:                 };
 233:                 (fs::File::open(p)?, idx_file)
 234:             }
 235:             (&Some(ref p), &Some(ref ip)) => {
 236:                 (fs::File::open(p)?, fs::File::open(ip)?)
 237:             }
 238:         };
 239:         // If the CSV data was last modified after the index file was last
 240:         // modified, then return an error and demand the user regenerate the
 241:         // index.
 242:         let data_modified = util::last_modified(&csv_file.metadata()?);
 243:         let idx_modified = util::last_modified(&idx_file.metadata()?);
 244:         if data_modified > idx_modified {
 245:             return Err(io::Error::new(
 246:                 io::ErrorKind::Other,
 247:                 "The CSV file was modified after the index file. \
 248:                  Please re-create the index.",
 249:             ));
 250:         }
 251:         let csv_rdr = self.from_reader(csv_file);
 252:         Ok(Some((csv_rdr, idx_file)))
 253:     }
